def main():
    out = {}
    for f in FILES:
        src = open(os.path.join(ROOT, f), encoding='utf-8').read()
        # apostrophes inside English words become typographic so they can never terminate a JS string
        lst = [[nl, re.sub(r"(?<=[A-Za-z])'(?=[a-z])", '\u2019', en)] for nl, en in PAIRS if nl in src]
        # longest first so a short pair never pre-empts a longer one
        lst.sort(key=lambda p: -len(p[0]))
        out[f] = lst
    json.dump(out, open(os.path.join(ROOT, '.i18n', 'js_replacements.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    for f, l in out.items():
        print(f, len(l))

if __name__ == '__main__':
    main()
